// Mendukung akses terbuka untuk keluarga besar maupun tautan personal (?to=Nama)
// ============================================================================
const INVITED_GUESTS = [
  'Bapak/Ibu/Saudara/i Tamu Kehormatan',
  'Keluarga Besar Afrizal Chaniago',
  'Keluarga Besar Joniter',
  'Keluarga Besar Raswim, M.Pd',
  'Keluarga Besar Harmain Lubis, SE. Ak.',
  'Keluarga Besar H. Sartono',
  'Keluarga Besar H. M. Yusuf',
  'Segenap Keluarga Besar (Padang) Sumatera Barat',
  'Keluarga Besar Bpk. Rahmat & Ibu Tajeriah',
];

const createGuestSlug = (text = '') =>
  text
    .toString()
    .toLowerCase()
    .trim()
    .replace(/&/g, ' ')
    .replace(/\bdan\b/g, ' ')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');

const findAuthorizedGuest = (rawCandidate) => {
  if (!rawCandidate) return null;
  const decoded = decodeURIComponent(rawCandidate).trim();
  if (!decoded) return null;

  const targetSlug = createGuestSlug(decoded);
  const targetNormalized = decoded.toLowerCase().replace(/\s+/g, ' ');

  const exactMatch = INVITED_GUESTS.find((guest) => {
    const guestSlug = createGuestSlug(guest);
    const guestNormalized = guest.toLowerCase().replace(/\s+/g, ' ');
    return guestSlug === targetSlug || guestNormalized === targetNormalized;
  });

  if (targetSlug === 'miwadmin') return null;

  return exactMatch || decoded;
};

// Deteksi apakah halaman diakses melalui subdomain miwadmin.* atau path /miwadmin
const checkIsMiwAdminRoute = () => {
  if (typeof window === 'undefined') return false;
  const host = (window.location.hostname || '').toLowerCase();
  const path = (window.location.pathname || '').toLowerCase().replace(/^\/+|\/+$/g, '');
  const hash = (window.location.hash || '').toLowerCase();
  const params = new URLSearchParams(window.location.search);

  return (
    host.startsWith('miwadmin.') ||
    host.includes('.miwadmin.') ||
    path === 'miwadmin' ||
    path.startsWith('miwadmin/') ||
    path.endsWith('/miwadmin') ||
    hash.includes('miwadmin') ||
    params.get('admin') === 'miwadmin' ||
    params.get('miwadmin') === '1'
  );
};

