const handleImageFallback = (e, fallbackSrc) => {
  const img = e.currentTarget;
  const currentAttr = img.getAttribute('src') || '';
  if (currentAttr.startsWith('/') && !currentAttr.startsWith('public/') && !img.dataset.triedPublic) {
    img.dataset.triedPublic = '1';
    img.src = `public${currentAttr}`;
    return;
  }
  if (fallbackSrc && img.src !== fallbackSrc && !img.dataset.triedFallback) {
    img.dataset.triedFallback = '1';
    img.src = fallbackSrc;
  }
};

